// Interoperability tests: the Dart crypto must read what the WEB app wrote (fixtures generated by
// tool/gen_vectors.mjs from apps/web/src/e2ee/envelope.ts), and must write what the web can read
// (build/dart_envelope.json, checked afterwards by tool/verify_dart_envelope.mjs in CI).
import 'dart:convert';
import 'dart:io';

import 'package:elisecurechat/crypto/envelope.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  final vectors = jsonDecode(File('test/fixtures/web_vectors.json').readAsStringSync()) as Map<String, dynamic>;
  final chatId = vectors['chatId'] as String;
  final senderId = vectors['senderId'] as String;
  final fd = vectors['flutterDevice'] as Map<String, dynamic>;
  final me = DeviceKeys.fromScalars(fd['deviceId'] as String, fd['agreementD'] as String, fd['signingD'] as String);
  final webSender = vectors['webSender'] as Map<String, dynamic>;
  final webSigningKey = webSender['signingKey'] as String;

  test('public keys derived in Dart equal the WebCrypto raw exports', () {
    expect(me.agreementKey, fd['agreementKey']);
    expect(me.signingKey, fd['signingKey']);
  });

  test('decrypts and verifies messages encrypted by the web app', () {
    for (final m in (vectors['messages'] as List).cast<Map<String, dynamic>>()) {
      final env = parseEnvelope(m['content'] as String);
      expect(env, isNotNull);
      final r = decryptEnvelope(envelope: env!, chatId: chatId, senderId: senderId, me: me, senderSigningKey: webSigningKey);
      expect(r.ok, isTrue, reason: 'failure: ${r.failure}');
      expect(r.verified, isTrue);
      expect(r.text, m['plaintext']);
    }
  });

  test('a message not sealed for this device is reported as such', () {
    final r = decryptEnvelope(envelope: parseEnvelope(vectors['notMine'] as String)!, chatId: chatId, senderId: senderId, me: me, senderSigningKey: webSigningKey);
    expect(r.failure, DecryptFailure.notForThisDevice);
  });

  test('tampering, a different chat or a different sender is rejected', () {
    final content = ((vectors['messages'] as List).first as Map)['content'] as String;
    final tampered = parseEnvelope(content)!;
    final ct = tampered['ct'] as String;
    tampered['ct'] = ct.substring(0, ct.length - 4) + (ct.endsWith('AAAA') ? 'BBBB' : 'AAAA');
    expect(decryptEnvelope(envelope: tampered, chatId: chatId, senderId: senderId, me: me, senderSigningKey: webSigningKey).failure, DecryptFailure.badSignature);
    expect(decryptEnvelope(envelope: parseEnvelope(content)!, chatId: 'another-chat', senderId: senderId, me: me, senderSigningKey: webSigningKey).failure, DecryptFailure.badSignature);
    expect(decryptEnvelope(envelope: parseEnvelope(content)!, chatId: chatId, senderId: 'someone-else', me: me, senderSigningKey: webSigningKey).failure, DecryptFailure.badSignature);
    // Without a known signing key the text still decrypts but is marked unverified.
    final unverified = decryptEnvelope(envelope: parseEnvelope(content)!, chatId: chatId, senderId: senderId, me: me);
    expect(unverified.ok && !unverified.verified, isTrue);
  });

  test('safety code matches the web app', () {
    final s = vectors['safety'] as Map<String, dynamic>;
    final a = s['a'] as Map<String, dynamic>;
    final b = s['b'] as Map<String, dynamic>;
    final code = safetyCode(
      userA: a['userId'] as String,
      keysA: (a['signingKeys'] as List).cast<String>(),
      userB: b['userId'] as String,
      keysB: (b['signingKeys'] as List).cast<String>(),
    );
    expect(code, s['code']);
    // Order of the two users does not matter.
    expect(safetyCode(userA: b['userId'] as String, keysA: (b['signingKeys'] as List).cast<String>(), userB: a['userId'] as String, keysB: (a['signingKeys'] as List).cast<String>()), s['code']);
  });

  test('Dart round trip, and device keys survive storage', () {
    final alice = DeviceKeys.generate('dev-dart-alice');
    final bob = DeviceKeys.fromJson(DeviceKeys.generate('dev-dart-bob').toJson());
    final restored = DeviceKeys.fromJson(jsonDecode(jsonEncode(bob.toJson())) as Map<String, dynamic>);
    expect(restored.agreementKey, bob.agreementKey);
    final content = encryptEnvelope(
      plaintext: 'round trip ✓',
      chatId: 'c1',
      senderId: 'u-alice',
      sender: alice,
      recipients: [PublicDevice(deviceId: bob.deviceId, userId: 'u-bob', agreementKey: bob.agreementKey, signingKey: bob.signingKey)],
    );
    final r = decryptEnvelope(envelope: parseEnvelope(content)!, chatId: 'c1', senderId: 'u-alice', me: restored, senderSigningKey: alice.signingKey);
    expect(r.ok && r.verified, isTrue);
    expect(r.text, 'round trip ✓');
  });

  test('writes Dart-encrypted messages for the web-side check', () {
    final nr = vectors['nodeRecipient'] as Map<String, dynamic>;
    final sender = DeviceKeys.generate('dev-dart-sender-0005');
    const dartChat = 'chat-dart-interop';
    const dartSender = 'user-dart-sender';
    final recipients = [
      PublicDevice(deviceId: nr['deviceId'] as String, userId: 'user-node', agreementKey: nr['agreementKey'] as String, signingKey: nr['signingKey'] as String),
      PublicDevice(deviceId: sender.deviceId, userId: dartSender, agreementKey: sender.agreementKey, signingKey: sender.signingKey),
    ];
    final messages = [
      for (final text in ['Hello from the Flutter app', 'Unicode ✓ नमस्ते 👋 "quotes" \\ /slash/'])
        {'plaintext': text, 'content': encryptEnvelope(plaintext: text, chatId: dartChat, senderId: dartSender, sender: sender, recipients: recipients)},
    ];
    final keysA = [sender.signingKey];
    final keysB = [nr['signingKey'] as String];
    final out = {
      'chatId': dartChat,
      'senderId': dartSender,
      'senderSigningKey': sender.signingKey,
      'messages': messages,
      'safety': {
        'a': {'userId': dartSender, 'signingKeys': keysA},
        'b': {'userId': 'user-node', 'signingKeys': keysB},
        'code': safetyCode(userA: dartSender, keysA: keysA, userB: 'user-node', keysB: keysB),
      },
    };
    Directory('build').createSync(recursive: true);
    File('build/dart_envelope.json').writeAsStringSync(jsonEncode(out));
    expect(File('build/dart_envelope.json').existsSync(), isTrue);
  });
}
